135	    public Builder(String context, Configuration conf) {
136	      if (isValid(context)) {
137	        sb.append(context);
138	      }
139	      fieldSeparator = conf.get(HADOOP_CALLER_CONTEXT_SEPARATOR_KEY,
140	          HADOOP_CALLER_CONTEXT_SEPARATOR_DEFAULT);
141	      checkFieldSeparator(fieldSeparator);
142	    }
143	
144	    public Builder(String context, String separator) {
145	      if (isValid(context)) {
146	        sb.append(context);
147	      }
148	      fieldSeparator = separator;
149	      checkFieldSeparator(fieldSeparator);
150	    }
