254	  /**
255	   * The thread local current caller context.
256	   * <p>
257	   * Internal class for defered singleton idiom.
258	   * https://en.wikipedia.org/wiki/Initialization_on_demand_holder_idiom
259	   */
260	  private static final class CurrentCallerContextHolder {
261	    static final ThreadLocal<CallerContext> CALLER_CONTEXT =
262	        new InheritableThreadLocal<>();
263	  }
264	
265	  public static CallerContext getCurrent() {
266	    return CurrentCallerContextHolder.CALLER_CONTEXT.get();
267	  }
268	
269	  public static void setCurrent(CallerContext callerContext) {
270	    CurrentCallerContextHolder.CALLER_CONTEXT.set(callerContext);
271	  }
