46	  public void testBuilderAppendIfAbsent() {
47	    Configuration conf = new Configuration();
48	    conf.set(HADOOP_CALLER_CONTEXT_SEPARATOR_KEY, "$");
49	    CallerContext.Builder builder = new CallerContext.Builder(null, conf);
50	    builder.append("key1", "value1");
