53	    // Append an existed key with different value.
54	    builder.appendIfAbsent("key1", "value2");
55	    String[] items = builder.build().getContext().split("\\$");
56	    Assert.assertEquals(1, items.length);
57	    Assert.assertEquals("key1:value1", builder.build().getContext());
58	
59	    // Append an absent key.
60	    builder.appendIfAbsent("key2", "value2");
61	    String[] items2 = builder.build().getContext().split("\\$");
62	    Assert.assertEquals(2, items2.length);
63	    Assert.assertEquals("key1:value1$key2:value2",
64	        builder.build().getContext());
65	
66	    // Append a key that is a substring of an existing key.
67	    builder.appendIfAbsent("key", "value");
68	    String[] items3 = builder.build().getContext().split("\\$");
69	    Assert.assertEquals(3, items3.length);
70	    Assert.assertEquals("key1:value1$key2:value2$key:value",
71	        builder.build().getContext());
72	  }
